package httpapi

const channelManageCSS = `
*{box-sizing:border-box;border-radius:0!important}
body{margin:0;background:#fff;color:#111;font:14px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans SC",sans-serif}
a{color:#0366d6;text-decoration:none}a:hover{text-decoration:underline}
.page{max-width:980px;margin:0 auto;padding:24px 20px 72px}.narrow{max-width:620px}
nav{font-size:13px;margin-bottom:24px}h1{font-size:30px;line-height:1.2;margin:8px 0}h2{font-size:19px;margin:0 0 12px;padding-bottom:6px;border-bottom:2px solid #111}h3{font-size:15px;margin:0 0 8px}
.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;border-bottom:3px solid #111;padding-bottom:18px;margin-bottom:18px}.account{text-align:right;font-size:12px;color:#555}
.panel{border:1px solid #bbb;padding:16px;margin:12px 0;background:#fff}.panel.strong{border:2px solid #111}.error{color:#c00;font-weight:700}.success{border:1px solid #0a7a0a;color:#0a7a0a;padding:10px;margin:12px 0}.muted{color:#666;font-size:13px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}
label{display:block;font-size:13px;font-weight:700;margin:10px 0 4px}input,textarea,select{width:100%;padding:9px 10px;border:1px solid #999;background:#fff;color:#111;font:14px inherit;margin:0 0 8px}textarea{resize:vertical}
button,.button{display:inline-block;border:2px solid #111;background:#111;color:#fff;padding:8px 16px;font-weight:700;cursor:pointer;text-decoration:none;font-size:13px}.button.secondary,button.secondary{background:#fff;color:#111}.button.danger,button.danger{background:#fff;color:#a00;border-color:#a00}
.actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.channel-list{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 22px}.channel-link{display:block;border:1px solid #999;color:#111;padding:9px 12px;min-width:140px}.channel-link.active{border:2px solid #111;background:#111;color:#fff}.channel-link small{display:block;color:inherit;opacity:.7}
.summary{display:grid;grid-template-columns:72px 1fr;gap:14px;align-items:center}.avatar{width:72px;height:72px;object-fit:cover;border:1px solid #999}.avatar.blank{display:flex;align-items:center;justify-content:center;background:#eee;font-size:28px;font-weight:700}.avatar-row{display:flex;align-items:center;margin:4px 0 10px}.avatar-preview{width:64px;height:64px;object-fit:cover;border:1px solid #999;background:#fff}.avatar-preview.placeholder{display:flex;align-items:center;justify-content:center;background:#eee;font-size:22px;font-weight:700;color:#666}.badge{display:inline-block;border:1px solid #777;padding:1px 7px;margin-right:5px;font-size:11px;text-transform:uppercase}
.columns{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:16px;align-items:start}.stack>*:first-child{margin-top:0}.post{padding:12px 0;border-bottom:1px solid #ddd}.post:last-child{border-bottom:0}.post-head{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:#666}.post-body{white-space:pre-wrap;word-break:break-word;margin:5px 0}.team-row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:8px 0;border-bottom:1px solid #ddd}.inline-form{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:end}.inline-form input{margin:0}.file{border:1px dashed #777;padding:12px;margin:8px 0}.file input{border:0;padding:0;margin:4px 0 0}
@media(max-width:760px){.page{padding:18px 14px 60px}.top{display:block}.account{text-align:left;margin-top:8px}.columns{display:block}.channel-link{flex:1 1 140px}.inline-form{display:block}.inline-form button{width:100%;margin-top:6px}}
`

const channelDashboardHTMLV2 = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>频道控制台 - OldChat</title><style>` + channelManageCSS + `</style></head><body><main class="page">
<nav><a href="/">HOME</a> / <a href="/channel-api.md">DEVELOPER DOC</a> / <a href="/channel-api/apply">TOKEN</a> / <a href="/channel-manage/logout">LOGOUT</a></nav>
<header class="top"><div><h1>频道控制台</h1><div class="muted">发布内容、管理频道资料和发言成员。</div></div><div class="account"><b>{{.UserUID}}</b><br>scope: <span class="mono">{{.Scopes}}</span></div></header>
{{if .Message}}<div class="success">{{.Message}}</div>{{end}}
<div class="actions"><b>我的频道</b>{{if .CanCreate}}<a class="button secondary" href="/channel-manage/register">创建频道</a>{{end}}</div>
<div class="channel-list">{{range .Channels}}<a class="channel-link {{if and $.Selected (eq .ID $.Selected.ID)}}active{{end}}" href="/channel-manage?channel_id={{.ID}}"><b>{{.Name}}</b><small>{{if .Handle}}@{{.Handle}}{{else}}{{.ID}}{{end}}</small></a>{{else}}<span class="muted">暂无可管理频道</span>{{end}}</div>
{{if .Selected}}
<section class="panel strong"><div class="summary">{{if .Selected.AvatarURL}}<img class="avatar" src="{{.Selected.AvatarURL}}" alt="">{{else}}<div class="avatar blank">{{sliceName .Selected.Name}}</div>{{end}}<div><h2 style="border:0;margin:0;padding:0">{{.Selected.Name}}</h2><div><span class="badge">{{.SelectedRole}}</span><span class="badge">{{.Selected.Visibility}}</span><span class="mono">{{.Selected.ID}}</span></div><div class="muted">{{if .Selected.Handle}}@{{.Selected.Handle}} · {{end}}{{.Selected.SubscriberCount}} 位订阅者</div><div>{{.Selected.Description}}</div></div></div></section>
<div class="columns"><div class="stack">
{{if .CanPost}}<section class="panel strong"><h2>发布消息</h2><form method="post" action="/channel-manage/post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="channel_id" value="{{.Selected.ID}}"><label>正文</label><textarea name="body" rows="5" maxlength="131072" placeholder="输入频道消息"></textarea><label class="file">附件（可选，最大 50MB）<input type="file" name="media" accept="image/*,audio/*,video/*"></label><button type="submit">发布消息</button></form></section>{{else}}<section class="panel"><h2>发布消息</h2><p class="error">当前 Token 缺少 channel:post 权限。</p></section>{{end}}
<section class="panel"><h2>最近消息</h2>{{range .Posts}}<article class="post"><div class="post-head"><b>{{.AuthorUID}}</b><span>#{{.PostSeq}} · {{.CreatedAt.Format "2006-01-02 15:04"}}</span></div><div class="post-body">{{.Body}}</div>{{if .MediaURL}}<a href="{{.MediaURL}}" target="_blank" rel="noopener">查看附件（{{.MsgType}}）</a>{{end}}</article>{{else}}<div class="muted">暂无消息</div>{{end}}</section>
</div><aside>
{{if .IsOwner}}<section class="panel"><h2>频道资料</h2><form method="post" action="/channel-manage/update"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="channel_id" value="{{.Selected.ID}}"><input type="hidden" name="action" value="name"><label>频道名称</label><input type="text" name="name" value="{{.Selected.Name}}" maxlength="64" required><button type="submit">保存名称</button></form><form method="post" action="/channel-manage/update" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="channel_id" value="{{.Selected.ID}}"><input type="hidden" name="action" value="avatar"><label>频道头像</label><div class="avatar-row">{{if .Selected.AvatarURL}}<img class="avatar-preview" src="{{.Selected.AvatarURL}}" alt="当前头像">{{else}}<div class="avatar-preview placeholder">{{sliceName .Selected.Name}}</div>{{end}}</div><label class="file">上传新头像（图片，最大 2MB）<input type="file" name="avatar_file" accept="image/*"></label><label>或填写头像 URL</label><input type="url" name="avatar_url" value="" placeholder="https://...（可选，二选一）"><button type="submit">保存头像</button></form><form method="post" action="/channel-manage/update"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="channel_id" value="{{.Selected.ID}}"><input type="hidden" name="action" value="description"><label>频道描述</label><textarea name="description" rows="3" maxlength="500">{{.Selected.Description}}</textarea><button type="submit">保存描述</button></form></section>
<section class="panel"><h2>发言成员</h2><form class="inline-form" method="post" action="/channel-manage/publisher"><div><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="channel_id" value="{{.Selected.ID}}"><input name="uid" placeholder="用户 UID / NCUID" required></div><button name="action" value="grant" type="submit">授权</button></form>{{range .Publishers}}<div class="team-row"><span><b>{{.Username}}</b><br><span class="muted">{{.UID}} · {{.Role}}</span></span>{{if ne .Role "owner"}}<form method="post" action="/channel-manage/publisher"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="channel_id" value="{{$.Selected.ID}}"><input type="hidden" name="uid" value="{{.UID}}"><button class="danger" name="action" value="revoke" type="submit">撤销</button></form>{{end}}</div>{{end}}</section>{{else}}<section class="panel"><h2>当前权限</h2><p>你可以发布频道消息。</p><p class="muted">频道资料及发言成员仅频道所有者可管理。</p></section>{{end}}
</aside></div>
{{else}}<section class="panel strong"><h2>尚无频道</h2>{{if .CanCreate}}<p>创建频道后即可在此发布与管理内容。</p><a class="button" href="/channel-manage/register">创建第一个频道</a>{{else}}<p>当前 Token 没有 <code>channel:create</code> 权限，且账号没有被授权管理任何频道。</p>{{end}}</section>{{end}}
</main></body></html>`
